class Solution {
    public int distributeCandies(int[] candyType) {
        java.util.HashSet<Integer> distinctTypes = new java.util.HashSet<>();
        for (int type : candyType) {
            distinctTypes.add(type);
        }
        int capacity = candyType.length / 2;
        return Math.min(distinctTypes.size(), capacity);
    }
}

class Solution {
    public int distributeCandies(int[] candyType) {
        java.util.Arrays.sort(candyType);
        int distinct = 1;
        for (int i = 1; i < candyType.length; i++) {
            if (candyType[i] != candyType[i - 1]) {
                distinct++;
            }
        }
        int capacity = candyType.length / 2;
        return Math.min(distinct, capacity);
    }
}

class Solution {
    public int distributeCandies(int[] candyType) {
        boolean[] seen = new boolean[200001];
        int distinct = 0;
        int capacity = candyType.length / 2;
        for (int type : candyType) {
            int index = type + 100000;
            if (!seen[index]) {
                seen[index] = true;
                distinct++;
                if (distinct == capacity) {
                    return capacity;
                }
            }
        }
        return distinct;
    }
}
